package com.sisge.ms.entity;
import jakarta.persistence.*; import java.time.Instant; import com.sisge.ms.entity.Rol;
@Entity @Table(name="usuarios") public class Usuario { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; private String nombre; private String apellido; @Column(nullable=false,unique=true) private String email; @Column(name="password_hash",nullable=false) private String passwordHash; @Column(nullable=false) private String estado="ACTIVO"; @ManyToOne @JoinColumn(name="rol_global_id") private Rol rolGlobal; @Column(name="created_at",nullable=false) private Instant createdAt=Instant.now(); @Column(name="updated_at",nullable=false) private Instant updatedAt=Instant.now(); public Long getId(){return id;} public String getEmail(){return email;} public String getPasswordHash(){return passwordHash;} public String getEstado(){return estado;} public Rol getRolGlobal(){return rolGlobal;} public void bootstrap(String e,String hash,Rol role){email=e;passwordHash=hash;nombre="Administrador";apellido="General";rolGlobal=role;} }
